function validate([words, puzzles]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100000) return 'words needs 1 to 10^5 strings.';
  if (!Array.isArray(puzzles) || puzzles.length < 1 || puzzles.length > 10000) return 'puzzles needs 1 to 10^4 strings.';
  for (const w of words) {
    if (typeof w !== 'string' || w.length < 4 || w.length > 50) return 'Each word has 4 to 50 letters.';
    if (!/^[a-z]+$/.test(w)) return 'Words use only lowercase English letters.';
  }
  for (const p of puzzles) {
    if (typeof p !== 'string' || p.length !== 7) return 'Each puzzle has exactly 7 letters.';
    if (!/^[a-z]+$/.test(p)) return 'Puzzles use only lowercase English letters.';
    if (new Set(p).size !== 7) return 'A puzzle cannot repeat a letter.';
  }
  return null;
}

