function findNumOfValidWords(words, puzzles) {
  const maskCount = new Map();
  for (const word of words) {
    let mask = 0;
    for (const ch of word) {
      mask |= 1 << (ch.charCodeAt(0) - 97);
    }
    maskCount.set(mask, (maskCount.get(mask) || 0) + 1);
  }

  const answer = [];
  for (const puzzle of puzzles) {
    const firstBit = 1 << (puzzle.charCodeAt(0) - 97);
    let rest = 0;
    for (let i = 1; i < puzzle.length; i++) {
      rest |= 1 << (puzzle.charCodeAt(i) - 97);
    }
    let total = 0;
    let subset = rest;
    while (true) {
      total += maskCount.get(subset | firstBit) || 0;
      if (subset === 0) {
        break;
      }
      subset = (subset - 1) & rest;
    }
    answer.push(total);
  }
  return answer;
}

