function findNumOfValidWords(words, puzzles) {
  // Check every word against every puzzle letter by letter.
  return puzzles.map(p => {
    let fits = 0;
    for (const w of words) {
      if (!w.includes(p[0])) continue;
      let ok = true;
      for (const c of w) if (!p.includes(c)) { ok = false; break; }
      if (ok) fits++;
    }
    return fits;
  });
}

