function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const shuffle = (list) => {
    const out = list.slice();
    for (let i = out.length - 1; i > 0; i--) { const j = pick(i + 1); [out[i], out[j]] = [out[j], out[i]]; }
    return out;
  };
  const all = 'abcdefghijklmnopqrstuvwxyz'.split('');
  // A narrow pool of letters makes many words fit many puzzles.
  const pool = shuffle(all).slice(0, size === 'large' ? 8 + pick(5) : 7 + pick(3));
  const makePuzzle = () => shuffle(pool).slice(0, 7).join('');
  const makeWord = () => {
    const distinct = shuffle(pool).slice(0, 1 + pick(size === 'large' ? 7 : 5));
    if (rand() < 0.1) distinct.push(all[pick(26)]);
    const longWord = size === 'large' && rand() < 0.05;
    const length = longWord ? 4 + pick(47) : 4 + pick(size === 'large' ? 9 : 4);
    return Array.from({ length }, () => distinct[pick(distinct.length)]).join('');
  };
  if (size === 'large') {
    return [Array.from({ length: 2000 }, makeWord), Array.from({ length: 1000 }, makePuzzle)];
  }
  return [Array.from({ length: 1 + pick(6) }, makeWord), Array.from({ length: 1 + pick(4) }, makePuzzle)];
}
